// BAD: read and write mixed, layout forced on every loop turn
for (const card of cards) {
  card.style.height = card.offsetHeight + 10 + 'px';
}

// GOOD: batch reads, then batch writes in one animation frame
const heights = cards.map((c) => c.offsetHeight); // 1) read phase
requestAnimationFrame(() => {
  cards.forEach((c, i) => {
    c.style.transform = 'translateY(0)';           // compositor friendly
    c.style.height = heights[i] + 10 + 'px';       // 2) write phase
  });
});

let controller;

async function search(term) {
  controller?.abort();               // cancel the previous in-flight request
  controller = new AbortController();
  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(term)}`, {
      signal: controller.signal,
    });
    if (!res.ok) throw new Error(`Search failed: ${res.status}`);
    render(await res.json());
  } catch (err) {
    if (err.name !== 'AbortError') showError(err);  // aborts are expected
  }
}

